draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // cup
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();

  // liquid level
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 45, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2-40, H/2-40, 80, 20+20*Math.sin(t));

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2-100, 20, 0, 2*Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-80);
  ctx.lineTo(W/2, H/2-50); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-60);
  ctx.lineTo(W/2-30, H/2-40); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-60);
  ctx.lineTo(W/2+30, H/2-40); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-50);
  ctx.lineTo(W/2, H/2-20); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-50);
  ctx.lineTo(W/2-20, H/2-30); // leg
  ctx.stroke();

  ctx.restore();
}
